import { test } from "node:test";
import assert from "node:assert/strict";
import { clamp } from "../src/math.js";

test("clamp keeps values inside the range", () => assert.equal(clamp(2, 0, 3), 2));
test("clamp caps values above max", () => assert.equal(clamp(5, 0, 3), 3));
test("clamp floors values below min", () => assert.equal(clamp(-2, 0, 3), 0));
